(() => {
'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='ataogo-concept-v1', TODAY='2026-10-04', roles=['Management','Project Manager','Procurement Officer','HSE Officer','Store/Materials Officer','Equipment/Asset Officer'];
const modules=[['dashboard','◫','Executive Dashboard'],['projects','▣','Projects'],['procurement','⇄','Procurement'],['materials','▤','Materials / Stores'],['equipment','⚙','Equipment / Assets'],['field','⌁','Field Operations'],['hse','◇','HSE / Safety'],['documents','▧','Document Control'],['team','♙','Workforce / Team'],['reports','▥','Reporting'],['activity','◷','Activity Log']];
let db=structuredClone(DEMO_DATA),role='Management',page='dashboard',recordId=null,tab='Overview',filters={},report=null,search='',lastFocus=null;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1){db=saved.db;role=roles.includes(saved.role)?saved.role:role;}}catch{}
const money=v=>'₦'+Number(v).toLocaleString('en-NG'),shortMoney=v=>'₦'+(v/1000000).toFixed(1)+'m';
const project=id=>db.projects.find(p=>p.id===id), pname=id=>project(id)?.name||'Unassigned';
const title=key=>modules.find(m=>m[0]===key)?.[2]||key;
const badge=s=>`<span class="badge ${/Completed|Approved|Resolved|Available|Good|Valid/.test(s)?'green':/Rejected|Out of Service|At Risk|Critical|Expired|Delayed|Out of Stock|Overdue/.test(s)?'red':/Review|Pending|Inspection|High|Maintenance|Low Stock|On Hold|Expiring Soon/.test(s)?'amber':'blue'}">${esc(s)}</span>`;
const stock=m=>m.qty===0?'Out of Stock':m.qty-m.reserved<=m.reorder?'Low Stock':'In Stock';
const cert=w=>w.cert<TODAY?'Expired':w.cert<'2026-11-04'?'Expiring Soon':'Valid';
const button=(text,action,attrs='',cls='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const openBtn=(text,module,id,cls='record')=>button(esc(text),'open',`data-module="${module}" data-id="${esc(id)}"`,cls);
const goto=(text,module)=>button(text,'goto',`data-module="${module}"`,'text-btn');
function persist(){try{localStorage.setItem(KEY,JSON.stringify({version:1,db,role}));}catch{toast('Browser storage unavailable. Changes remain for this session.');}}
function toast(text){const el=document.createElement('div');el.className='toast';el.textContent=text;$('#toasts').append(el);while($('#toasts').children.length>3)$('#toasts').firstElementChild.remove();setTimeout(()=>el.remove(),4300);}
function log(text,module,id,p){const event={time:new Date().toISOString(),actor:`Kelvin Demo User · ${role}`,text,module,id,project:p||''};db.activity.unshift(event);db.notifications.unshift({text,module,id,read:false});persist();updateBell();}
function updateBell(){$('#notificationCount').textContent=db.notifications.filter(n=>!n.read).length;}
function navigate(module,id=null){page=module;recordId=id;tab='Overview';filters={};search='';$('#globalSearch').value='';report=null;document.body.classList.remove('menu-open');render();window.scrollTo(0,0);}
function heading(name,sub,actions=''){return `<div class="breadcrumb">Operations workspace / ${esc(title(page))}${recordId?' / '+esc(recordId):''}</div><div class="page-heading"><div><span class="eyebrow">${recordId?'RECORD DETAIL':'OPERATIONS INTELLIGENCE'}</span><h1>${esc(name)}</h1><p>${esc(sub)}</p></div><div class="toolbar">${actions||'<span class="date-chip">04 October 2026 · Demo snapshot</span>'}</div></div>`;}
function details(obj){return `<dl class="details">${Object.entries(obj).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${v}</dd></div>`).join('')}</dl>`;}
function metric(label,value,note,module,warn=false,filter=''){return `<button class="metric ${warn?'warn':''}" data-action="metric" data-module="${module}" data-filter="${filter}"><span class="metric-label">${label}<span>↗</span></span><strong>${value}</strong><small>${note}</small></button>`;}
function timeline(events){return `<ul class="timeline">${events.map(e=>`<li>${e.module?openBtn(e.text,e.module,e.id,'') : esc(e.text)}<small>${esc(e.actor||'Demo team')} · ${esc(new Date(e.time).toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}))}</small></li>`).join('')}</ul>`;}
const colors=['#26796b','#d3a053','#789ba3','#b87569','#8b98b1','#d3dacd'];
function chart(name,rows,donut=false){const total=rows.reduce((a,r)=>a+r[1],0);let sum=0;const gradient=rows.map((r,i)=>{const start=sum;sum+=total?r[1]/total*100:0;return `${colors[i%colors.length]} ${start}% ${sum}%`;}).join(',');return `<section class="panel"><div class="panel-heading"><h2>${name}</h2><span class="mini-tag">LIVE DEMO DATA</span></div>${donut?`<div class="chart-row"><div class="donut" style="background:${total?'conic-gradient('+gradient+')':'#edf1ee'}"><strong>${total}</strong></div><div class="legend">${rows.map((r,i)=>`<div><span class="dot" style="background:${colors[i%colors.length]}"></span>${esc(r[0])}<b>${r[1]}</b></div>`).join('')}</div></div>`:rows.map((r,i)=>`<div class="bar-row"><span>${esc(r[0])}</span><div class="bar-track"><div class="bar-fill" style="width:${total?r[1]/Math.max(...rows.map(x=>x[1]),1)*100:0}%;background:${colors[i%colors.length]}"></div></div><b>${r[1]}</b></div>`).join('')}</section>`;}
function dashboard(){const pending=db.procurement.filter(p=>['Submitted','Under Review'].includes(p.status)).length;return heading('Operational overview','A connected view of fictional projects, resources and decisions.')+`<div class="story-banner"><span class="number">01 → 08</span><div><h3>Follow one request across the operation</h3><p>Delta Flowline · Inspect a field request, approve procurement, receive materials and review project readiness.</p></div>${button('Explore example project →','open','data-module="projects" data-id="P-001"')}</div><div class="metrics">`+
metric('Active Projects',db.projects.filter(p=>['Active','At Risk'].includes(p.status)).length,'Across the sample portfolio','projects')+metric('Projects At Risk',db.projects.filter(p=>p.status==='At Risk').length,'Review mobilisation dependencies','projects',true,'At Risk')+metric('Pending Procurement',pending,'Requests awaiting a decision','procurement',true,'pending')+metric('Equipment in Operation',db.equipment.filter(e=>e.status==='Assigned').length,'Assigned and cleared for use','equipment',false,'Assigned')+metric('Equipment Due for Maintenance',db.equipment.filter(e=>['Under Maintenance','Inspection Due'].includes(e.status)).length,'Maintenance or inspection attention','equipment',true,'attention')+metric('Open HSE Actions',db.hse.filter(h=>h.status==='Open').length,'Corrective actions to close','hse',true,'Open')+metric('Pending Approvals',pending+db.documents.filter(d=>d.status==='Under Review').length,'Procurement and document reviews','approvals',true)+metric('Field Activities in Progress',db.field.filter(f=>f.status==='In Progress').length,role==='Management'?'View the field-to-office connection':`Emphasis for ${role}`,'field',false,'In Progress')+'</div>'+`<div class="grid-equal">${chart('Project status',['Active','Completed','At Risk','On Hold'].map(s=>[s,db.projects.filter(p=>p.status===s).length]),true)}${chart('Procurement pipeline',[['Requested',db.procurement.filter(p=>['Draft','Submitted'].includes(p.status)).length],['Under Review',db.procurement.filter(p=>p.status==='Under Review').length],['Approved',db.procurement.filter(p=>p.status==='Approved').length],['Ordered',db.procurement.filter(p=>['Ordered','Partially Received'].includes(p.status)).length],['Received',db.procurement.filter(p=>p.status==='Completed').length]])}${chart('Equipment availability',[['Available',db.equipment.filter(e=>e.status==='Available').length],['Assigned',db.equipment.filter(e=>e.status==='Assigned').length],['Attention',db.equipment.filter(e=>['Inspection Due','Under Maintenance'].includes(e.status)).length],['Out of Service',db.equipment.filter(e=>e.status==='Out of Service').length]],true)}</div><div class="grid-2"><section class="panel"><div class="panel-heading"><h2>Project watchlist</h2>${goto('All projects →','projects')}</div>${table('projects',db.projects)}</section><section class="panel"><div class="panel-heading"><h2>Recent activity</h2>${goto('Full log →','activity')}</div>${timeline(db.activity.slice(0,5))}</section></div><div class="callout teal"><strong>Simulated role: ${esc(role)}.</strong> ${role==='Management'?'You can review procurement decisions and project visibility.':role==='Procurement Officer'?'You can review requests, select vendors and create sample orders.':role==='Store/Materials Officer'?'You can receive ordered materials and see stock updates.':role==='Equipment/Asset Officer'?'You can manage equipment assignment and readiness.':role==='HSE Officer'?'You can resolve corrective actions with closure notes.':'You can submit field and procurement requests.'} Role controls are frontend illustrations; production access control would require a secure backend.</div>`;}
const schemas={
projects:['Project / client','Status','Progress','Budget'],procurement:['Request / project','Requester','Priority','Estimated cost','Date','Status'],materials:['Material / allocation','Category','On hand','Reserved','Free stock','Reorder','Location','Stock status'],equipment:['Asset / project','Category','Location','Next maintenance','Utilization','Availability'],field:['Activity / project','Team / supervisor','Location','Date','Status'],hse:['Record / project','Type','Risk','Action owner','Due','Status'],documents:['Document / project','Category','Version','Owner','Date','Status'],team:['Worker / role','Department','Project','Location','Certification','Availability']};
function table(module,rows){if(!rows.length)return '<div class="empty">No records match these filters.</div>';const cells=r=>{const first=`${openBtn(r.id+' · '+r.name,module,r.id)}<small>${esc(module==='projects'?r.client:pname(r.project))}</small>`;switch(module){case'projects':return [first,badge(r.status),`${r.progress}%<div class="progress"><span style="width:${r.progress}%"></span></div>`,shortMoney(r.budget)];case'procurement':return[first,esc(r.requester),badge(r.priority),money(r.cost),r.date,badge(r.status)];case'materials':return[first,esc(r.category),`${r.qty} ${r.unit}`,r.reserved,r.qty-r.reserved,r.reorder,esc(r.location),badge(stock(r))];case'equipment':return[first,esc(r.category),esc(r.location),r.next,`${r.utilization}%`,badge(r.status)];case'field':return[first,`${esc(r.team)}<small>${esc(r.supervisor)}</small>`,esc(r.location),r.date,badge(r.status)];case'hse':return[first,esc(r.type),badge(r.risk),esc(r.responsible),r.due,badge(r.status)];case'documents':return[first,esc(r.category),esc(r.version),esc(r.owner),r.date,badge(r.status)];case'team':return[`${openBtn(r.id+' · '+r.name,module,r.id)}<small>${esc(r.role)}</small>`,esc(r.department),esc(pname(r.project)),esc(r.location),`${badge(cert(r))}<small>Expires ${r.cert}</small>`,badge(r.status)];}};return `<div class="table-wrap"><table><thead><tr>${schemas[module].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cells(r).map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function selectFilter(key,label,values,placeholder='All'){return `<label>${label}<select data-filter="${key}"><option value="">${placeholder}</option>${values.map(v=>`<option value="${esc(Array.isArray(v)?v[0]:v)}" ${filters[key]===(Array.isArray(v)?v[0]:v)?'selected':''}>${esc(Array.isArray(v)?v[1]:v)}</option>`).join('')}</select></label>`;}
function filterControls(module){return `<div class="filters"><label>Search<input type="search" id="listSearch" placeholder="ID, title or person…" value="${esc(filters.q||'')}"></label>${module!=='projects'?selectFilter('project','Project',db.projects.map(p=>[p.id,p.name])):''}${selectFilter('status','Status',[...new Set(db[module].map(r=>module==='materials'?stock(r):r.status))])}${['materials','documents','equipment'].includes(module)?selectFilter('category','Category',[...new Set(db[module].map(r=>r.category))]):''}${module==='hse'?selectFilter('type','Record type',[...new Set(db.hse.map(r=>r.type))]):''}${button('Clear','clear')}<span class="result-count" id="resultCount"></span></div>`;}
function filtered(module){return db[module].filter(r=>(!filters.project||r.project===filters.project)&&(!filters.status||(module==='materials'?stock(r):r.status)===filters.status||(filters.status==='pending'&&['Submitted','Under Review'].includes(r.status))||(filters.status==='attention'&&['Inspection Due','Under Maintenance'].includes(r.status)))&&(!filters.category||r.category===filters.category)&&(!filters.type||r.type===filters.type)&&(!filters.q||JSON.stringify(r).toLowerCase().includes(filters.q.toLowerCase())||pname(r.project).toLowerCase().includes(filters.q.toLowerCase())));}
function cards(rows){return `<div class="project-grid">${rows.map(p=>`<article class="project-card"><div class="project-card-top"><span>${p.id} · EXAMPLE PROJECT</span>${badge(p.status)}</div><h2>${esc(p.name)}</h2><p>${esc(p.client)}<br>${esc(p.location)}</p><div class="progress-label"><span>Project progress</span><strong>${p.progress}%</strong></div><div class="progress"><span style="width:${p.progress}%"></span></div><div class="card-foot"><span>${esc(p.manager)}<br>Target ${p.end}</span>${openBtn('View project →','projects',p.id,'')}</div></article>`).join('')}</div>`;}
function list(module){let top=heading(title(module),{projects:'Example projects inspired by publicly described engineering services.',procurement:'Trace each request from field need to delivery and receipt.',materials:'Stock availability, reservations and project allocations.',equipment:'Equipment readiness, assignments and maintenance visibility.',field:'Site activities connected to resources, safety and evidence.',hse:'Illustrative inspections, incidents and corrective action ownership.',documents:'Technical evidence, revisions and review status.',team:'Operational assignments and certification visibility. All people are fictional.'}[module],module==='procurement'?button('+ New request','new-request','','primary'):module==='field'?button('+ Field activity','new-field','','primary'):'');
if(module==='hse')top+=`<div class="metrics">${metric('Open HSE Actions',db.hse.filter(r=>r.status==='Open').length,'Corrective action queue','hse',true,'Open')}${metric('Overdue Actions',db.hse.filter(r=>r.status==='Open'&&r.due<TODAY).length,'As at demo snapshot','hse',true,'overdue')}${metric('Inspections This Month',db.hse.filter(r=>r.type==='Safety inspection'&&r.date.startsWith('2026-10')).length,'Recorded in October 2026','hse',false,'inspections')}${metric('Open Incidents',db.hse.filter(r=>r.type==='Incident'&&r.status==='Open').length,'Sample incident reviews','hse',true,'incidents')}</div>`;
if(module==='procurement')top+=`<div class="steps">${['Project request','Review','Approval','Vendor selection','Purchase order','Delivery','Receipt'].map((s,i)=>`<span class="step ${i===2?'current':''}">${i+1}. ${s}</span>`).join('')}</div>`;
if(module==='materials')top+=`<div class="callout teal">MR-2026-008 · Delta Flowline requests <strong>2 inspection probe kits</strong> through ${openBtn('PR-2026-014','procurement','PR-2026-014','text-btn')}. Receipt increases stock here and updates the project trail.</div>`;
if(module==='team')top+='<div class="callout">Certification warnings are sample operational signals. Validity must be verified before real mobilisation.</div>';
return top+filterControls(module)+'<div id="listResults"></div>';
}
function refreshList(){let rows=filtered(page);if(filters.special==='overdue')rows=rows.filter(r=>r.status==='Open'&&r.due<TODAY);if(filters.special==='inspections')rows=rows.filter(r=>r.type==='Safety inspection'&&r.date.startsWith('2026-10'));if(filters.special==='incidents')rows=rows.filter(r=>r.type==='Incident'&&r.status==='Open');$('#listResults').innerHTML=page==='projects'?(rows.length?cards(rows):'<div class="empty">No projects match.</div>'):table(page,rows);$('#resultCount').textContent=`${rows.length} records${filters.special?' · '+filters.special+' view':''}`;}
function projectDetail(p){const tabs=['Overview','Activities','Procurement','Materials','Equipment','HSE','Documents','Team','Reports'];let body='';if(tab==='Overview')body=`<div class="grid-2"><section class="panel"><div class="panel-heading"><h2>Project overview</h2>${badge(p.status)}</div><p>${esc(p.scope)}</p>${details({'Client':esc(p.client),'Location':esc(p.location),'Project manager':esc(p.manager),'Start date':p.date,'Expected completion':p.end,'Budget':money(p.budget),'Sample spend':money(p.spent),'Progress':p.progress+'%','Project ID':p.id})}<div class="progress-label"><span>Delivery progress</span><strong>${p.progress}%</strong></div><div class="progress"><span style="width:${p.progress}%"></span></div></section><section class="panel"><div class="panel-heading"><h2>Milestone plan</h2></div><div class="link-list">${p.milestones.map(m=>`<div class="notification-item">${esc(m[0])}<span style="margin-left:auto">${badge(m[1])}</span></div>`).join('')}</div></section></div>${p.id==='P-001'?`<section class="panel"><div class="panel-heading"><h2>Connected workflow · Delta Flowline</h2><span class="mini-tag">ILLUSTRATIVE WORKFLOW</span></div><div class="steps">${['Field request','Procurement review','Approval','Vendor & order','Material receipt','Equipment readiness','Safety closure','Reporting'].map((s,i)=>`<span class="step ${i<workflowStep()?'done':i===workflowStep()?'current':''}">${i+1}. ${s}</span>`).join('')}</div><div class="link-list">${openBtn('FO-001 · Inspect the field need','field','FO-001','')}${openBtn('PR-2026-014 · '+db.procurement[0].status,'procurement','PR-2026-014','')}${openBtn('MAT-011 · '+db.materials.find(m=>m.id==='MAT-011').qty+' probe kits on hand','materials','MAT-011','')}${openBtn('EQ-003 · '+db.equipment[2].status,'equipment','EQ-003','')}${openBtn('HSE-ACT-019 · '+db.hse[1].status,'hse','HSE-2026-033','')}${openBtn('DOC-001 · Inspection method statement','documents','DOC-001','')}${button('View integrated project report →','project-report',`data-id="${p.id}"`)}</div></section>`:''}`;
else if(tab==='Reports')body=reportView(p.id);
else{const key={Activities:'field',Procurement:'procurement',Materials:'materials',Equipment:'equipment',HSE:'hse',Documents:'documents',Team:'team'}[tab];body=table(key,db[key].filter(r=>r.project===p.id));}
return heading(p.name,'Example project · Fictional client, team, budget and operational records.',button('← All projects','goto','data-module="projects"'))+`<div class="tabs">${tabs.map(t=>button(t,'tab',`data-tab="${t}"`,tab===t?'active':'')).join('')}</div>`+body+`<section class="panel audit-panel"><div class="panel-heading"><h2>Project activity trail</h2></div>${timeline(db.activity.filter(a=>a.project===p.id).slice(0,6))}</section>`;}
function workflowStep(){const pr=db.procurement[0];if(pr.status==='Completed'){if(db.equipment[2].status!=='Assigned')return 5;if(db.hse[1].status!=='Resolved')return 6;return 7;}if(['Ordered','Partially Received'].includes(pr.status))return 4;if(pr.status==='Approved')return 3;return 2;}
function can(type){return ({approve:['Management'],order:['Procurement Officer'],review:['Procurement Officer'],submit:['Project Manager','Procurement Officer'],receive:['Store/Materials Officer'],equipment:['Equipment/Asset Officer'],hse:['HSE Officer'],field:['Project Manager'],document:['Project Manager','HSE Officer']}[type]||[]).includes(role);}
function permission(type){return can(type)?'':`<p class="inline-note">Switch the simulated role to ${({approve:'Management',order:'Procurement Officer',review:'Procurement Officer',submit:'Project Manager',receive:'Store/Materials Officer',equipment:'Equipment/Asset Officer',hse:'HSE Officer',field:'Project Manager',document:'Project Manager'})[type]} to perform this demo action.</p>`;}
function actionBtn(text,type,action,attrs='',cls='primary'){return button(text,action,`${attrs} ${can(type)?'':'disabled'}`,cls);}
function recordDetail(module,r){if(module==='projects')return projectDetail(r);if(module==='equipment')return equipmentDetail(r);let html=heading(r.id+' · '+r.name,'Sample record · '+pname(r.project),button('← '+title(module),'goto',`data-module="${module}"`));
if(module==='procurement'){const states=['Draft','Submitted','Under Review','Approved','Ordered','Partially Received','Completed'];html+=`<div class="steps">${states.map((s,i)=>`<span class="step ${i<states.indexOf(r.status)?'done':s===r.status?'current':''}">${s}</span>`).join('')}${r.status==='Rejected'?'<span class="step current">Rejected</span>':''}</div><div class="grid-2"><section class="panel"><div class="panel-heading"><h2>Request details</h2>${badge(r.status)}</div>${details({'Project':openBtn(pname(r.project),'projects',r.project,'text-btn'),'Requester':esc(r.requester),'Department':esc(r.department),'Priority':badge(r.priority),'Request date':r.date,'Estimated cost':money(r.cost)})}<div class="callout teal">${esc(r.reason)}</div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Quantity</th><th>Unit cost</th><th>Total</th></tr></thead><tbody>${r.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.qty} ${esc(i.unit)}</td><td>${money(i.cost)}</td><td>${money(i.cost*i.qty)}</td></tr>`).join('')}</tbody></table></div><div class="actions">${r.status==='Draft'?actionBtn('Submit request','submit','transition',`data-id="${r.id}" data-status="Submitted"`):''}${r.status==='Submitted'?actionBtn('Start review','review','transition',`data-id="${r.id}" data-status="Under Review"`):''}${r.status==='Under Review'?actionBtn('Approve request','approve','approve',`data-id="${r.id}"`)+actionBtn('Reject with reason','approve','reject',`data-id="${r.id}"`,'danger'):''}${r.status==='Approved'?actionBtn('Select vendor & create PO','order','order',`data-id="${r.id}"`):''}${['Ordered','Partially Received'].includes(r.status)?actionBtn('Record delivery / receipt','receive','receipt',`data-id="${r.id}"`):''}</div>${permission(r.status==='Under Review'?'approve':r.status==='Approved'?'order':['Ordered','Partially Received'].includes(r.status)?'receive':r.status==='Submitted'?'review':'submit')}${r.rejection?`<div class="callout">Rejection reason: ${esc(r.rejection)}</div>`:''}</section><section class="panel"><div class="panel-heading"><h2>Fulfilment & linked records</h2></div>${details({'Vendor':esc(r.vendor||'Pending selection'),'Purchase order':esc(r.po||'Not yet issued'),'Received':r.received+' / '+r.items.reduce((a,i)=>a+i.qty,0)+' '+r.items[0].unit,'Approval':r.approvedBy?esc(r.approvedBy)+'<br><small>'+esc(r.approvedAt)+'</small>':'Pending'})}<div class="link-list">${r.material?openBtn('Linked material · '+r.material,'materials',r.material,''):''}${openBtn('Example project →','projects',r.project,'')}${r.id==='PR-2026-014'?openBtn('Originating field activity · FO-001','field','FO-001',''):''}</div>${db.receipts.filter(x=>x.pr===r.id).map(x=>`<div class="callout teal">${esc(x.id)} · ${x.qty} received<br><small>${esc(x.note)} · ${esc(x.date)}</small></div>`).join('')}</section></div>`;}
if(module==='materials')html+=`<section class="panel"><div class="panel-heading"><h2>Material availability</h2>${badge(stock(r))}</div>${details({'Material code':r.id,'Description':esc(r.name),'Category':esc(r.category),'On hand':r.qty+' '+r.unit,'Reserved':r.reserved+' '+r.unit,'Free stock':(r.qty-r.reserved)+' '+r.unit,'Reorder level':r.reorder+' '+r.unit,'Store location':esc(r.location),'Project allocation':openBtn(pname(r.project),'projects',r.project,'text-btn')})}<div class="callout">${r.qty===0?'No stock on hand. Complete the linked procurement receipt to see this balance update.':'Free stock is on-hand quantity minus project reservations. Reservations do not represent consumption.'}</div><h3>Linked procurement</h3>${table('procurement',db.procurement.filter(p=>p.material===r.id))}${db.receipts.filter(x=>x.material===r.id).length?'<h3 style="margin-top:22px">Receipt history</h3>'+db.receipts.filter(x=>x.material===r.id).map(x=>`<p>${esc(x.id)} · ${x.qty} ${esc(r.unit)} · ${esc(x.note)}</p>`).join(''):''}</section>`;
if(module==='field')html+=`<div class="grid-2"><section class="panel"><div class="panel-heading"><h2>Field activity</h2>${badge(r.status)}</div>${details({'Project':openBtn(pname(r.project),'projects',r.project,'text-btn'),'Location':esc(r.location),'Assigned team':esc(r.team),'Activity type':esc(r.name),'Date':r.date,'Supervisor':esc(r.supervisor)})}<div class="callout teal">${esc(r.notes)}</div>${actionBtn('Update activity status','field','field-update',`data-id="${r.id}"`)}${permission('field')}${r.id==='FO-001'?`<h3 style="margin-top:24px">Resource dependencies</h3><div class="link-list">${openBtn('MR-2026-008 / PR-2026-014 · '+db.procurement[0].status,'procurement','PR-2026-014','')}${openBtn('EQ-003 · '+db.equipment[2].status,'equipment','EQ-003','')}${openBtn('HSE-ACT-019 · '+db.hse[1].status,'hse','HSE-2026-033','')}</div>`:''}</section><section class="panel"><div class="panel-heading"><h2>Activity timeline</h2></div>${timeline([{text:'Activity planned and supervisor assigned',actor:r.supervisor,time:r.date+'T08:00:00'},...db.activity.filter(a=>a.id===r.id)])}</section></div>`;
if(module==='hse')html+=`<div class="grid-2"><section class="panel"><div class="panel-heading"><h2>${esc(r.type)}</h2>${badge(r.risk)}</div>${details({'Project':openBtn(pname(r.project),'projects',r.project,'text-btn'),'Location':esc(r.location),'Inspector / owner':esc(r.owner),'Date':r.date,'Record status':badge(r.status),'Corrective action':r.actionId})}<h3 style="margin-top:22px">Findings</h3><p>${esc(r.finding)}</p></section><section class="panel"><div class="panel-heading"><h2>Corrective action</h2>${badge(r.status)}</div><p>${esc(r.action)}</p>${details({'Responsible person':esc(r.responsible),'Due date':r.due,'Due indicator':r.status==='Open'&&r.due<TODAY?badge('Overdue'):badge(r.status==='Resolved'?'Resolved':'Pending')})}${r.status==='Open'?actionBtn('Resolve with closure note','hse','resolve',`data-id="${r.id}"`)+permission('hse'):`<div class="callout teal">Resolved${r.closure?': '+esc(r.closure):' · sample closure record'}</div>`}</section></div>`;
if(module==='documents')html+=`<section class="panel"><div class="panel-heading"><h2>Document register</h2>${badge(r.status)}</div>${details({'Document ID':r.id,'Category':esc(r.category),'Project':openBtn(pname(r.project),'projects',r.project,'text-btn'),'Version':esc(r.version),'Owner':esc(r.owner),'Date':r.date})}<div class="actions">${button('Preview document','preview',`data-id="${r.id}"`,'primary')}${button('Download sample text','download-doc',`data-id="${r.id}"`)}${r.status==='Draft'?actionBtn('Submit for review','document','doc-transition',`data-id="${r.id}" data-status="Under Review"`):r.status==='Under Review'?actionBtn('Approve sample document','document','doc-transition',`data-id="${r.id}" data-status="Approved"`):''}</div><div class="document-preview">${esc(r.body)}</div><h3 style="margin-top:22px">Version history</h3>${timeline([{text:'Version '+r.version+' · '+r.status,actor:r.owner,time:r.date+'T09:00:00'},...(r.history||[])])}<p class="inline-note">This textual preview illustrates a document workflow. No real engineering drawing, permit or certificate is provided.</p></section>`;
if(module==='team')html+=`<section class="panel"><div class="panel-heading"><h2>Operational workforce profile</h2>${badge(r.status)}</div>${details({'Worker ID':r.id,'Name':esc(r.name),'Role':esc(r.role),'Department':esc(r.department),'Project':openBtn(pname(r.project),'projects',r.project,'text-btn'),'Location':esc(r.location),'Certification expiry':r.cert,'Certification status':badge(cert(r)),'Availability':badge(r.status)})}<div class="callout">All workers and certification dates are fictional. ${cert(r)==='Expired'?'Demo mobilisation warning: certification renewal needs review.':cert(r)==='Expiring Soon'?'Demo attention: arrange certification review before expiry.':'Illustrative certification record is within its sample validity period.'}</div></section>`;
return html+`<section class="panel audit-panel"><div class="panel-heading"><h2>Record activity trail</h2></div>${db.activity.some(a=>a.id===r.id)?timeline(db.activity.filter(a=>a.id===r.id)):'<p class="small">Actions performed in this demo will appear here.</p>'}</section>`;
}
function equipmentDetail(r){const tabs=['Overview','Assignment History','Maintenance','Inspections','Documents'];let body='';if(tab==='Overview')body=`<section class="panel"><div class="panel-heading"><h2>Asset readiness</h2>${badge(r.status)}</div>${details({'Asset ID':r.id,'Equipment':esc(r.name),'Category':esc(r.category),'Current location':esc(r.location),'Assigned project':r.project?openBtn(pname(r.project),'projects',r.project,'text-btn'):'Unassigned','Responsible department':esc(r.department),'Condition':esc(r.condition),'Availability':badge(r.status),'Last maintenance':r.last,'Next maintenance':r.next,'Utilization':r.utilization+'%'})}<div class="actions">${actionBtn('Change assignment / status','equipment','asset-update',`data-id="${r.id}"`)}</div>${permission('equipment')}<div class="callout">Assignment shows allocation. Equipment marked Inspection Due, Under Maintenance or Out of Service is not counted as operationally available.</div></section>`;
if(tab==='Assignment History')body=`<section class="panel"><h2>Assignment history</h2>${timeline([{text:r.project?'Allocated to '+pname(r.project):'Returned to equipment yard',actor:'Equipment Officer',time:r.date+'T08:30:00'},...db.assignments.filter(x=>x.id===r.id)])}</section>`;
if(tab==='Maintenance')body=`<section class="panel"><h2>Maintenance plan</h2>${details({'Last recorded maintenance':r.last,'Next planned maintenance':r.next,'Current condition':esc(r.condition),'Availability':badge(r.status)})}<div class="callout">Maintenance and inspection dates are sample records. Updating the demo status does not certify real equipment.</div>${actionBtn('Update asset record','equipment','asset-update',`data-id="${r.id}"`)}</section>`;
if(tab==='Inspections')body=`<section class="panel"><h2>Inspection readiness</h2>${r.id==='EQ-003'?'<div class="callout">Inspection/calibration clearance pending. Sample certificate DOC-002 is expired. Renew evidence before marking this asset Assigned.</div>':'<p>Sample readiness review: verify certificates and condition before mobilisation.</p>'}${badge(r.status)}<div class="actions">${actionBtn('Record inspection & clearance','equipment','inspection',`data-id="${r.id}"`)}</div>${r.inspection?`<div class="callout teal">${esc(r.inspection)}</div>`:''}</section>`;
if(tab==='Documents')body=table('documents',db.documents.filter(d=>r.id==='EQ-003'?d.id==='DOC-002':d.project===r.project&&d.category==='Equipment Certificates'));
return heading(r.id+' · '+r.name,'Demo asset · Assignment, readiness and maintenance history.',button('← Equipment','goto','data-module="equipment"'))+`<div class="tabs">${tabs.map(t=>button(t,'tab',`data-tab="${t}"`,tab===t?'active':'')).join('')}</div>`+body;}
const reportTypes=['Integrated Operations','Project Performance','Procurement Summary','Equipment Utilization','Material Consumption','HSE Performance','Outstanding Actions','Project Activity Summary'];
function reportControls(p=''){return `<form id="reportForm"><div class="filters"><label>Report<select name="type">${reportTypes.map(t=>`<option ${report?.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Project<select name="project"><option value="">All projects</option>${db.projects.map(x=>`<option value="${x.id}" ${(report?.project??p)===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>From<input name="from" type="date" value="${report?.from||'2026-07-01'}" required></label><label>To<input name="to" type="date" value="${report?.to||TODAY}" required></label><label>Department<select name="department"><option value="">All departments</option>${['Projects','Engineering','Procurement','Field Operations','Equipment','HSE','Logistics'].map(d=>`<option ${report?.department===d?'selected':''}>${d}</option>`).join('')}</select></label><label>Status<select name="status"><option value="">All statuses</option>${[...new Set(['Open',...['projects','procurement','equipment','field','hse','documents'].flatMap(k=>db[k].map(x=>x.status))])].map(s=>`<option ${report?.status===s?'selected':''}>${s}</option>`).join('')}</select></label><button class="primary" type="submit">Generate Report</button></div></form>`;}
function reportData(){const q=report||{project:'',from:'2026-07-01',to:TODAY,department:'',status:'',type:'Integrated Operations'};const keys=q.type==='Project Performance'?['projects']:q.type==='Procurement Summary'?['procurement']:q.type==='Equipment Utilization'?['equipment']:q.type==='HSE Performance'?['hse']:q.type==='Project Activity Summary'?['field']:q.type==='Outstanding Actions'?['procurement','hse','documents']:['projects','procurement','equipment','hse','field'];let rows=keys.flatMap(k=>db[k].map(r=>({...r,module:k,project:k==='projects'?r.id:r.project,department:r.department||'Projects'})));rows=rows.filter(r=>(!q.project||r.project===q.project)&&r.date>=q.from&&r.date<=q.to&&(!q.department||r.department===q.department)&&(!q.status||r.status===q.status)&&(q.type!=='Outstanding Actions'||['Under Review','Submitted','Open','Delayed','Inspection Due'].includes(r.status)));return rows;}
function reportView(p=''){if(!report)report={type:'Integrated Operations',project:p,from:'2026-07-01',to:TODAY,department:'',status:''};return reportControls(p)+`<div class="actions">${button('Export CSV','export','','primary')}${button('Print report','print')}</div><div id="reportOutput">${reportOutput()}</div>`;}
function reportOutput(){const rows=reportData(),q=report; if(q.type==='Material Consumption'){const receipts=db.receipts.filter(r=>(!q.project||r.project===q.project)&&r.date.slice(0,10)>=q.from&&r.date.slice(0,10)<=q.to&&(!q.department||q.department==='Stores')&&(!q.status||q.status==='Received'));return `<section class="panel"><h2>Material Consumption · Illustrative report</h2><p>Receipt quantities are shown separately. No material consumption issues have been recorded in this prototype, so consumption is not inferred from procurement or reservations.</p><p class="snapshot">${esc(q.from)} → ${esc(q.to)} · ${esc(q.project?pname(q.project):'All projects')}</p><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Material</th><th>Project</th><th>Quantity received</th><th>Date</th></tr></thead><tbody>${receipts.map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(r.material)}</td><td>${esc(pname(r.project))}</td><td>${r.qty}</td><td>${r.date.slice(0,10)}</td></tr>`).join('')||'<tr><td colspan="5">No receipts match the selected filters.</td></tr>'}</tbody></table></div><div class="callout">Consumed: 0 recorded issues. Reserved stock represents allocation only.</div></section>`;}
return `<section class="panel"><div class="panel-heading"><h2>${esc(q.type)}</h2><span class="mini-tag">SAMPLE DATA</span></div><p class="snapshot">${esc(q.project?pname(q.project):'All projects')} · ${esc(q.from)} → ${esc(q.to)} · ${esc(q.department||'All departments')} · ${esc(q.status||'All statuses')}</p><div class="report-summary"><div>Matched records<strong>${rows.length}</strong></div><div>Procurement value<strong>${shortMoney(rows.filter(r=>r.module==='procurement').reduce((a,r)=>a+r.cost,0))}</strong></div><div>Mean asset utilization<strong>${rows.some(r=>r.module==='equipment')?Math.round(rows.filter(r=>r.module==='equipment').reduce((a,r)=>a+r.utilization,0)/rows.filter(r=>r.module==='equipment').length)+'%':'—'}</strong></div><div>Open HSE actions<strong>${rows.filter(r=>r.module==='hse'&&r.status==='Open').length}</strong></div></div><div class="report-chart">${['projects','procurement','equipment','hse','field'].map((k,i)=>`<div class="bar-row"><span>${esc(title(k))}</span><div class="bar-track"><div class="bar-fill" style="width:${rows.length?rows.filter(r=>r.module===k).length/rows.length*100:0}%;background:${colors[i]}"></div></div><b>${rows.filter(r=>r.module===k).length}</b></div>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Record</th><th>Module</th><th>Project</th><th>Date</th><th>Status</th><th>Indicator</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${openBtn(r.id+' · '+r.name,r.module,r.id)}</td><td>${esc(title(r.module))}</td><td>${esc(pname(r.project))}</td><td>${r.date}</td><td>${badge(r.status)}</td><td>${r.module==='projects'?r.progress+'% progress':r.module==='procurement'?money(r.cost):r.module==='equipment'?r.utilization+'% utilization':r.module==='hse'?esc(r.risk)+' risk':esc(r.team)}</td></tr>`).join('')||'<tr><td colspan="6">No records match these filters.</td></tr>'}</tbody></table></div><p class="inline-note">Date filters use each record’s displayed date. This is a current-state sample report, not historical state reconstruction. Financial figures are fictional.</p></section>`;}
function approvals(){return heading('Approval queue','Sample procurement and document decisions waiting for review.')+'<section class="panel"><h2>Procurement decisions</h2>'+table('procurement',db.procurement.filter(r=>['Submitted','Under Review'].includes(r.status)))+'<h2 style="margin-top:25px">Document reviews</h2>'+table('documents',db.documents.filter(r=>r.status==='Under Review'))+'</section>';}
function searchResults(){let results=['projects','procurement','materials','equipment','field','hse','documents','team'].flatMap(k=>db[k].filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase())||pname(r.project).toLowerCase().includes(search.toLowerCase())).map(r=>({k,r})));return heading('Search results',`${results.length} records matching “${search}”`)+`<section class="panel"><div class="link-list">${results.map(({k,r})=>`<button data-action="open" data-module="${k}" data-id="${r.id}"><span>${esc(r.id+' · '+r.name)}<small>${esc(title(k))} · ${esc(pname(r.project))}</small></span><span>→</span></button>`).join('')||'<div class="empty">No matching records.</div>'}</div></section>`;}
function render(){document.title=(recordId||title(page))+' · ATAOGO Concept';$('#nav').innerHTML=modules.map(([key,icon,name])=>`<button data-action="goto" data-module="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}><span>${icon}</span><span>${name}</span></button>`).join('');let content;if(page==='search')content=searchResults();else if(page==='approvals')content=approvals();else if(page==='dashboard')content=dashboard();else if(page==='reports')content=heading('Management reporting','Connect project, procurement, equipment and safety information.')+reportView();else if(page==='activity')content=heading('Activity log','Browser-local demonstration history. Production audit trails would require protected server storage.',button('Reset sample data','reset','','danger'))+`<section class="panel">${timeline(db.activity)}</section>`;else if(recordId){const r=db[page]?.find(r=>r.id===recordId);content=r?recordDetail(page,r):heading('Record not found','Return to the module to select another sample record.',button('Back','goto',`data-module="${page}"`));}else content=list(page);$('#main').innerHTML=content;if($('#listResults'))refreshList();updateBell();}
function modal(name,body,foot=''){lastFocus=document.activeElement;$('#modalContent').innerHTML=`<div class="modal-head"><h2 id="modalTitle">${esc(name)}</h2>${button('×','close','aria-label="Close dialog"','icon-btn')}</div><div class="modal-body">${body}</div>${foot?'<div class="modal-footer">'+foot+'</div>':''}`;if(!$('#modal').open)$('#modal').showModal();}
function close(){if($('#modal').open)$('#modal').close();lastFocus?.focus();}
function confirm(name,body,action,attrs=''){modal(name,body,button('Cancel','close')+button('Confirm','confirm',`data-confirm="${action}" ${attrs}`,'primary'));}
function notificationCenter(){modal('Notifications',`<div>${db.notifications.map((n,i)=>`<button class="notification-item ${!n.read?'unread':''}" data-action="notification" data-index="${i}"><span class="dot"></span>${esc(n.text)}<small>${n.read?'Viewed':'New'} →</small></button>`).join('')}</div>`,button('Mark all as read','mark-read'));}
function download(name,content,type='text/plain'){const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function exportReport(){const q=report;let rows;if(q.type==='Material Consumption')rows=[['Receipt','Material','Project','Quantity received','Date'],...db.receipts.filter(r=>(!q.project||r.project===q.project)&&r.date.slice(0,10)>=q.from&&r.date.slice(0,10)<=q.to&&(!q.department||q.department==='Stores')&&(!q.status||q.status==='Received')).map(r=>[r.id,r.material,pname(r.project),r.qty,r.date]),['Consumption','No recorded material issues']];else rows=[['ID','Title','Module','Project','Date','Department','Status','Cost (NGN)','Utilization (%)','Risk'],...reportData().map(r=>[r.id,r.name,title(r.module),pname(r.project),r.date,r.department,r.status,r.cost??'',r.utilization??'',r.risk??''])];const csv=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';download('ataogo-sample-report.csv','\uFEFF'+rows.map(r=>r.map(csv).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Sample report exported as CSV.');}
function showForm(name,id,body,label='Save'){modal(name,`<form id="${id}">${body}<div class="actions"><button type="submit" class="primary">${label}</button>${button('Cancel','close')}</div></form>`);}
function options(values,current){return values.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('');}
function projectsOptions(current){return db.projects.map(p=>`<option value="${p.id}" ${p.id===current?'selected':''}>${esc(p.name)}</option>`).join('');}
function allowed(type){if(can(type))return true;toast('Choose the appropriate simulated role for this action.');return false;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;const pr=db.procurement.find(r=>r.id===id),eq=db.equipment.find(r=>r.id===id),h=db.hse.find(r=>r.id===id),f=db.field.find(r=>r.id===id);
if(a==='goto')navigate(b.dataset.module);if(a==='open'){close();navigate(b.dataset.module,id);}if(a==='tab'){tab=b.dataset.tab;render();}if(a==='close')close();if(a==='clear'){filters={};render();}if(a==='metric'){navigate(b.dataset.module==='approvals'?'approvals':b.dataset.module);if(b.dataset.filter){if(['overdue','inspections','incidents'].includes(b.dataset.filter))filters.special=b.dataset.filter;else filters.status=b.dataset.filter;render();}}if(a==='project-report'){navigate('reports');report={type:'Integrated Operations',project:id,from:'2026-07-01',to:TODAY,department:'',status:''};render();}
if(a==='approve'&&pr&&allowed('approve'))confirm('Approve '+id,`<p>Approve the sample request for <strong>${money(pr.cost)}</strong>?</p><div class="callout teal">This records a demo decision and notifies the next department. Vendor selection and ordering remain separate steps.</div>`,'approve',`data-id="${id}"`);
if(a==='transition'&&pr){const type=b.dataset.status==='Under Review'?'review':'submit';if(allowed(type))confirm('Move request to '+b.dataset.status,`<p>${esc(pr.name)} · ${esc(id)}</p>`,'transition',`data-id="${id}" data-status="${b.dataset.status}"`);}
if(a==='reject'&&pr&&allowed('approve'))showForm('Reject '+id,'rejectForm',`<input type="hidden" name="id" value="${id}"><label class="form-label">Reason (required)<textarea name="reason" minlength="8" maxlength="500" required></textarea></label>`,'Reject request');
if(a==='order'&&pr&&allowed('order'))showForm('Vendor selection & purchase order','orderForm',`<input type="hidden" name="id" value="${id}"><div class="callout">Fictional vendors. No real order is sent.</div><div class="form-grid"><label>Selected vendor<select name="vendor" required><option value="">Choose vendor</option>${options(['Delta Technical Supply (fictional)','Creek Safety Supply (fictional)','Rivergate Industrial Supply (fictional)'])}</select></label><label>Expected delivery<input name="delivery" type="date" min="2026-10-04" value="2026-10-08" required></label><label class="wide">Selection rationale<textarea name="rationale" minlength="8" required maxlength="500" placeholder="Technical compliance, delivery and value…"></textarea></label></div>`,'Create sample PO');
if(a==='receipt'&&pr&&allowed('receive')){const left=pr.items[0].qty-pr.received;showForm('Receive materials · '+id,'receiptForm',`<input type="hidden" name="id" value="${id}"><div class="callout teal">${esc(pr.items[0].name)} · ${left} ${esc(pr.items[0].unit)} outstanding. Receipt updates linked stock.</div><div class="form-grid"><label>Quantity received<input name="qty" type="number" min="1" max="${left}" step="1" value="${left}" required></label><label>Delivery / receipt reference<input name="note" minlength="3" maxlength="100" required placeholder="e.g. Delivery note DEMO-014"></label></div>`,'Record receipt');}
if(a==='asset-update'&&eq&&allowed('equipment'))showForm('Update '+id,'assetForm',`<input type="hidden" name="id" value="${id}"><div class="form-grid"><label>Assigned project<select name="project"><option value="">Unassigned</option>${projectsOptions(eq.project)}</select></label><label>Availability<select name="status">${options(['Available','Assigned','Under Maintenance','Inspection Due','Out of Service'],eq.status)}</select></label><label>Location<input name="location" value="${esc(eq.location)}" required maxlength="100"></label><label>Condition<input name="condition" value="${esc(eq.condition)}" required maxlength="100"></label><label>Next maintenance<input name="next" type="date" value="${eq.next}" required></label><label class="wide">Change note<textarea name="note" minlength="8" required maxlength="500"></textarea></label></div>`);
if(a==='inspection'&&eq&&allowed('equipment'))showForm('Record inspection clearance','inspectionForm',`<input type="hidden" name="id" value="${id}"><div class="callout">Sample clearance only. This does not certify actual equipment.</div><label class="form-label">Inspection evidence / note<textarea name="note" minlength="12" maxlength="500" required></textarea></label><label class="form-label">Next inspection date<input name="expiry" type="date" min="2026-10-05" value="2027-01-04" required></label>`,'Record sample clearance');
if(a==='resolve'&&h&&allowed('hse'))showForm('Resolve '+h.actionId,'resolveForm',`<input type="hidden" name="id" value="${id}"><p>${esc(h.action)}</p><label class="form-label">Closure evidence / verification<textarea name="note" minlength="12" maxlength="500" required placeholder="Describe the corrective action and verification…"></textarea></label>`,'Mark resolved');
if(a==='field-update'&&f&&allowed('field'))showForm('Update field activity','fieldForm',`<input type="hidden" name="id" value="${id}"><label class="form-label">Status<select name="status">${options(['Scheduled','In Progress','Completed','Delayed'],f.status)}</select></label><label class="form-label">Supervisor update<textarea name="note" minlength="8" maxlength="500" required></textarea></label>`);
if(a==='preview'){const d=db.documents.find(r=>r.id===id);modal(d.name,`<p>${esc(d.id)} · Version ${esc(d.version)} · ${badge(d.status)}</p><div class="document-preview">${esc(d.body)}</div>`,button('Download sample','download-doc',`data-id="${id}"`));}
if(a==='download-doc'){const d=db.documents.find(r=>r.id===id);download(d.id+'-sample.txt',d.name+'\nVersion '+d.version+'\nConcept Demonstration by Vecora Technologies\n\n'+d.body);toast('Sample document downloaded.');}
if(a==='doc-transition'&&allowed('document'))confirm('Update sample document',`<p>Move ${esc(id)} to ${esc(b.dataset.status)}?</p>`,'document',`data-id="${id}" data-status="${b.dataset.status}"`);
if(a==='notification'){const n=db.notifications[Number(b.dataset.index)];n.read=true;persist();close();navigate(n.module,n.id);}if(a==='mark-read'){db.notifications.forEach(n=>n.read=true);persist();updateBell();notificationCenter();}if(a==='export')exportReport();if(a==='print')window.print();if(a==='reset')confirm('Reset the demonstration','<p>Restore all fictional records and clear changes made in this browser?</p>','reset');
if(a==='about')modal('About this concept',`<p><strong>ATAOGO Operations Hub</strong> is an independent concept demonstration prepared by Vecora Technologies. It is not an official Ataogo product.</p><p>The flowline scenario is inspired by Ataogo’s publicly described pipeline / flowline services, integrity management, EPC/EPCM, specialised procurement, and safety services.</p><p>Every project, client, person, asset, document and amount in this demo is fictional. These modules are illustrative possibilities, not confirmed requirements.</p><h3>Production capabilities to explore</h3><p>Server-enforced role and department access, protected audit trails, authentication, approval policies, document versioning, notifications and integrations would be designed after requirements discovery.</p><p class="small">This demo stores changes in your browser only. Role selection is a UI simulation, not secure access control. Do not enter confidential information.</p><p><a href="https://www.ataogoltd.com/" target="_blank" rel="noopener">Public service reference: Ataogo official website ↗</a></p>`);
if(a==='new-request'){if(!allowed('submit'))return;showForm('New sample procurement request','newRequestForm',`<div class="form-grid"><label class="wide">Request title<input name="name" required minlength="5" maxlength="100"></label><label>Project<select name="project">${projectsOptions('P-001')}</select></label><label>Priority<select name="priority">${options(['Medium','High','Low'])}</select></label><label>Requester<input name="requester" required maxlength="60"></label><label>Department<select name="department">${options(['Engineering','Field Operations','HSE','Procurement'])}</select></label><label>Material<select name="material">${db.materials.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></label><label>Quantity<input name="qty" type="number" min="1" max="10000" step="1" required></label><label>Unit cost (NGN)<input name="cost" type="number" min="1" max="1000000000" step="1" required></label><label class="wide">Operational justification<textarea name="reason" required minlength="12" maxlength="500"></textarea></label></div>`,'Create draft');}
if(a==='new-field'){if(!allowed('field'))return;showForm('New field activity','newFieldForm',`<div class="form-grid"><label>Activity type<select name="name">${options(['Pipeline inspection','Welding activity','Equipment installation','Tank cleaning','Mechanical maintenance','Offshore intervention','Site inspection'])}</select></label><label>Project<select name="project">${projectsOptions('P-001')}</select></label><label>Location<input name="location" required maxlength="100"></label><label>Date<input name="date" type="date" value="${TODAY}" required></label><label>Assigned team<input name="team" required maxlength="80"></label><label>Supervisor<input name="supervisor" required maxlength="80"></label><label class="wide">Notes<textarea name="notes" required minlength="12" maxlength="500"></textarea></label></div>`,'Schedule activity');}
if(a==='confirm'){const type=b.dataset.confirm;if(type==='reset'){db=structuredClone(DEMO_DATA);persist();close();navigate('dashboard');toast('Sample data restored.');return;}if(type==='approve'&&pr&&pr.status==='Under Review'&&allowed('approve')){pr.status='Approved';pr.approvedBy='Kelvin Demo User · '+role;pr.approvedAt=new Date().toLocaleString('en-GB');log(id+' approved; ready for vendor selection','procurement',id,pr.project);}if(type==='transition'&&pr){const typeRole=b.dataset.status==='Under Review'?'review':'submit';if(allowed(typeRole)){pr.status=b.dataset.status;log(id+' moved to '+pr.status,'procurement',id,pr.project);}}if(type==='document'&&allowed('document')){const d=db.documents.find(x=>x.id===id);d.status=b.dataset.status;(d.history??=[]).unshift({time:new Date().toISOString(),actor:'Kelvin Demo User',text:'Version '+d.version+' moved to '+d.status});log(id+' moved to '+d.status,'documents',id,d.project);}close();render();toast('Sample workflow updated.');}
});
document.addEventListener('submit',e=>{const form=e.target;if(!form.getAttribute('id'))return;e.preventDefault();if(!form.reportValidity())return;const v=Object.fromEntries(new FormData(form)),id=v.id,pr=db.procurement.find(r=>r.id===id),eq=db.equipment.find(r=>r.id===id);let text='';
if(form.getAttribute('id')==='reportForm'){const from=form.elements.from,to=form.elements.to;to.setCustomValidity(v.to<v.from?'End date must be on or after start date.':'');if(!form.reportValidity())return;report=v;$('#reportOutput').innerHTML=reportOutput();toast('Report generated from selected filters.');return;}
if(form.getAttribute('id')==='rejectForm'&&allowed('approve')&&pr.status==='Under Review'){pr.status='Rejected';pr.rejection=v.reason;text=id+' rejected: '+v.reason;log(text,'procurement',id,pr.project);}
if(form.getAttribute('id')==='orderForm'&&allowed('order')&&pr.status==='Approved'){pr.vendor=v.vendor;pr.delivery=v.delivery;pr.rationale=v.rationale;pr.po='PO-DEMO-'+String(db.procurement.filter(r=>r.po).length+1).padStart(3,'0');pr.status='Ordered';log(pr.po+' created for '+id+' · '+v.vendor,'procurement',id,pr.project);text='Sample PO created. Switch to Store/Materials Officer to receive delivery.';}
if(form.getAttribute('id')==='receiptForm'&&allowed('receive')&&['Ordered','Partially Received'].includes(pr.status)){const qty=Number(v.qty),left=pr.items[0].qty-pr.received;if(!Number.isInteger(qty)||qty<1||qty>left){toast('Receipt quantity exceeds the outstanding amount.');return;}pr.received+=qty;pr.status=pr.received===pr.items[0].qty?'Completed':'Partially Received';const m=db.materials.find(m=>m.id===pr.material);m.qty+=qty;const receipt={id:'GRN-DEMO-'+String(db.receipts.length+1).padStart(3,'0'),pr:id,material:m.id,project:pr.project,qty,note:v.note,date:new Date().toISOString()};db.receipts.unshift(receipt);log(receipt.id+' · '+qty+' '+m.unit+' received against '+id,'procurement',id,pr.project);text='Receipt recorded. Linked material stock updated.';}
if(form.getAttribute('id')==='assetForm'&&allowed('equipment')){if(v.status==='Assigned'&&!v.project){form.elements.project.setCustomValidity('Select a project before assigning equipment.');form.reportValidity();return;}if(v.status==='Assigned'&&eq.id==='EQ-003'&&!eq.inspection){toast('Record the sample inspection clearance in the Inspections tab first.');return;}eq.project=v.project;eq.status=v.status;eq.location=v.location;eq.condition=v.condition;eq.next=v.next;db.assignments.unshift({id,time:new Date().toISOString(),actor:role,text:v.note+' · '+v.status+' · '+pname(v.project)});log(id+' assignment/readiness updated: '+v.status,'equipment',id,v.project);text='Asset assignment and readiness updated.';}
if(form.getAttribute('id')==='inspectionForm'&&allowed('equipment')){eq.inspection=v.note;eq.condition='Good';eq.last=TODAY;eq.next=v.expiry;eq.status='Available';if(eq.id==='EQ-003'){const d=db.documents.find(d=>d.id==='DOC-002');(d.history??=[]).unshift({time:new Date().toISOString(),actor:role,text:'Sample certificate revision 1.0 superseded'});d.version='2.0';d.status='Approved';d.date=TODAY;d.body='SAMPLE CERTIFICATE · NOT A REAL CERTIFICATION\nAsset EQ-003\nDemo inspection: '+v.note+'\nNext inspection: '+v.expiry;}log(id+' sample inspection cleared; available for assignment','equipment',id,eq.project);text='Sample clearance recorded; certificate preview updated.';}
if(form.getAttribute('id')==='resolveForm'&&allowed('hse')){const h=db.hse.find(r=>r.id===id);h.status='Resolved';h.closure=v.note;log(h.actionId+' resolved: '+v.note,'hse',id,h.project);text='Corrective action marked resolved.';}
if(form.getAttribute('id')==='fieldForm'&&allowed('field')){const f=db.field.find(r=>r.id===id);if(id==='FO-001'&&v.status==='Completed'&&(db.procurement[0].status!=='Completed'||db.equipment[2].status!=='Assigned'||db.hse[1].status!=='Resolved')){toast('Complete procurement receipt, assign cleared EQ-003 and resolve HSE-ACT-019 before closing this survey.');return;}f.status=v.status;f.notes+='\nSupervisor update: '+v.note;log(id+' moved to '+v.status,'field',id,f.project);text='Field activity updated.';}
if(form.getAttribute('id')==='newRequestForm'&&allowed('submit')){const m=db.materials.find(m=>m.id===v.material),num=Math.max(...db.procurement.map(x=>Number(x.id.split('-').pop())));const r={id:'PR-2026-'+String(num+1).padStart(3,'0'),name:v.name,project:v.project,requester:v.requester,department:v.department,date:TODAY,status:'Draft',priority:v.priority,cost:Number(v.qty)*Number(v.cost),material:v.material,vendor:'',items:[{name:m.name,qty:Number(v.qty),unit:m.unit,cost:Number(v.cost)}],reason:v.reason,received:0};db.procurement.push(r);log(r.id+' created as a draft','procurement',r.id,r.project);close();navigate('procurement',r.id);toast('Draft created. Review and submit when ready.');return;}
if(form.getAttribute('id')==='newFieldForm'&&allowed('field')){const r={...v,id:'FO-'+String(db.field.length+1).padStart(3,'0'),department:'Field Operations',status:'Scheduled'};db.field.push(r);log(r.id+' scheduled: '+r.name,'field',r.id,r.project);close();navigate('field',r.id);toast('Field activity scheduled.');return;}
if(text){persist();close();render();toast(text);}
});
document.addEventListener('change',e=>{if(e.target.matches('[data-filter]')){filters[e.target.dataset.filter]=e.target.value;refreshList();}if(e.target.id==='role'){role=e.target.value;persist();render();toast('Simulated role changed to '+role+'.');}if(e.target.name==='project')e.target.setCustomValidity('');if(e.target.name==='to')e.target.setCustomValidity('');});
document.addEventListener('input',e=>{if(e.target.id==='listSearch'){filters.q=e.target.value;refreshList();}if(e.target.id==='globalSearch'){search=e.target.value.trim();if(search){page='search';recordId=null;render();}else navigate('dashboard');}});
$('#role').innerHTML=options(roles,role);$('#enter').onclick=()=>{$('#intro').hidden=true;$('#app').hidden=false;render();};$('#menu').onclick=()=>document.body.classList.toggle('menu-open');$('#scrim').onclick=()=>document.body.classList.remove('menu-open');$('#bell').onclick=notificationCenter;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});$('#modal').addEventListener('cancel',()=>{lastFocus?.focus();});updateBell();
})();
